<?php
declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';
use App\Security\Csrf;use App\Services\Auth;use App\Services\DocumentEpodService;
Auth::requireLogin();$id=(int)($_GET['id']??0);$uid=(int)Auth::user()['id'];$trip=DocumentEpodService::trip($id,$uid);if(!$trip){http_response_code(403);exit('Trip not found or access denied.');}$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid token.');$a=$_POST['action']??'';if($a==='upload')DocumentEpodService::upload($id,$_POST,$_FILES['document']??[],$uid);elseif($a==='submit_epod')DocumentEpodService::submitEpod($id,$_POST,$uid);elseif($a==='review_epod')DocumentEpodService::reviewEpod($id,(string)($_POST['decision']??''),(string)($_POST['notes']??''),$uid);else throw new RuntimeException('Invalid action.');header('Location: ?id='.$id.'&updated=1');exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}$trip=DocumentEpodService::trip($id,$uid);}
$docs=DocumentEpodService::documents($id,$uid);$epod=DocumentEpodService::epod($id,$uid);$canUpload=Auth::can('DOCUMENT_MANAGE_OPERATIONS')||(Auth::can('DOCUMENT_UPLOAD_DRIVER')&&(int)$trip['driver_user_id']===$uid);$canSubmit=(Auth::can('EPOD_SUBMIT_DRIVER')&&(int)$trip['driver_user_id']===$uid)||Auth::can('EPOD_REVIEW_OPERATIONS');$pageTitle='Documents '.$trip['trip_ref'];require BASE_PATH.'/app/Views/layout/header.php';?>
<div class="page-head"><div><h1>Documents & e-POD</h1><p><?=h($trip['trip_ref'].' · '.$trip['shipment_ref'].' · '.$trip['load_ref'].' · '.$trip['origin_city'].' → '.$trip['destination_city'])?></p></div><span class="badge"><?=h($trip['shipment_status'])?></span></div>
<?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?>
<?php if($canUpload):?><form method="post" enctype="multipart/form-data" class="card"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="action" value="upload"><h2>Upload transport document</h2>
<div class="form-grid"><div class="field"><label>Document type</label><select name="document_type"><option value="waybill">Waybill</option><option value="bill_of_lading">Bill of lading</option><option value="delivery_note">Delivery note</option><option value="customs">Customs</option><option value="inspection">Inspection</option><option value="delivery_evidence">Delivery evidence</option><option value="other">Other</option></select></div><div class="field"><label>Title</label><input name="title" maxlength="191"></div>
<?php if(Auth::can('DOCUMENT_MANAGE_OPERATIONS')):?><div class="field"><label>Visibility</label><select name="visibility_scope"><option value="involved_parties">All involved parties</option><option value="operations_only">Operations only</option><option value="shipper">Shipper only</option><option value="carrier">Carrier only</option><option value="driver">Driver only</option></select></div><?php endif;?>
<div class="field"><label>File (PDF, JPG, PNG or WebP; maximum 10 MB)</label><input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png,.webp" required></div></div><div class="field"><label>Description</label><textarea name="description" maxlength="500"></textarea></div><button class="button">Upload document</button></form><?php endif;?>
<div class="card table-wrap" style="margin-top:18px"><h2>Transport documents</h2><table><thead><tr><th>Document</th><th>Type</th><th>File</th><th>Size</th><th>Uploaded</th><th></th></tr></thead><tbody>
<?php foreach($docs as$d):?><tr><td><?=h($d['title'])?></td><td><?=h(str_replace('_',' ',$d['document_type']))?></td><td><?=h($d['original_file_name'])?></td><td><?=h(number_format((int)$d['byte_size']/1024,1).' KB')?></td><td><?=h(($d['uploaded_by']?:'System').' · '.$d['uploaded_at'])?></td><td><a href="<?=h(\App\Support\Url::to('documents/download.php?id='.$d['document_id']))?>">Download</a></td></tr><?php endforeach;?><?php if(!$docs):?><tr><td colspan="6" class="muted">No accessible documents.</td></tr><?php endif;?></tbody></table></div>
<div class="card" style="margin-top:18px"><h2>Electronic proof of delivery</h2>
<?php if(!$epod):?><p class="muted">No e-POD has been submitted.</p><?php else:?><p><strong><?=h($epod['epod_ref'])?></strong> · <?=h($epod['epod_status'])?></p><p>Result: <?=h($epod['delivery_result'])?> · Recipient: <?=h($epod['recipient_name'])?> · Delivered: <?=h($epod['delivered_at'])?></p><p>Signature name: <?=h($epod['signature_name'])?></p><p><?=h($epod['delivery_notes'])?></p><?php foreach($epod['confirmations'] as$c):?><p class="muted"><?=h($c['confirmed_at'].' · '.$c['decision'].' · '.$c['confirmation_notes'])?></p><?php endforeach;?><?php endif;?>
<?php if($canSubmit&&$trip['current_status']==='delivered'&&$trip['shipment_status']==='delivered_pending_epod'&&(!$epod||$epod['epod_status']==='rejected')):?><form method="post"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="action" value="submit_epod"><h3><?=h($epod?'Resubmit e-POD':'Submit e-POD')?></h3><p class="muted">Upload at least one document with type <strong>Delivery evidence</strong> before submitting.</p><div class="form-grid"><div class="field"><label>Delivery result</label><select name="delivery_result"><option value="delivered">Delivered</option><option value="partial">Partially delivered</option><option value="damaged">Delivered with damage</option><option value="refused">Refused</option></select></div><div class="field"><label>Delivered at</label><input type="datetime-local" name="delivered_at" value="<?=h(date('Y-m-d\TH:i',strtotime((string)$trip['delivered_at'])))?>" required></div><div class="field"><label>Recipient name</label><input name="recipient_name" maxlength="191" required></div><div class="field"><label>Recipient contact</label><input name="recipient_contact" maxlength="120"></div><div class="field"><label>Signature name</label><input name="signature_name" maxlength="191" required></div></div><div class="field"><label>Delivery notes</label><textarea name="delivery_notes"></textarea></div><button class="button">Submit e-POD for Operations review</button></form><?php endif;?>
<?php if(Auth::can('EPOD_REVIEW_OPERATIONS')&&$epod&&$epod['epod_status']==='submitted'):?><form method="post"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><input type="hidden" name="action" value="review_epod"><div class="field"><label>Review notes (required when rejecting)</label><textarea name="notes" maxlength="1000"></textarea></div><button class="button" name="decision" value="confirmed">Confirm e-POD</button> <button class="button" name="decision" value="rejected">Reject for correction</button></form><?php endif;?></div>
<?php require BASE_PATH.'/app/Views/layout/footer.php';?>